create table if not exists SZD_PRODUCTION.core_rel.t_external_delivery (
	delivery_nr varchar(250) not null comment 'business/natural key - the business identifier of the delivery.',
	event_dt date not null comment 'the date when the entry is found in the source.',
	client_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the party.',
	hauler_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the hauler party',
	carrying_hauler_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the company carrying the goods to the target.',
	recipient_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the party.',
	creditor_supplier_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the supplier/creditor party',
	supplier_party_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the supplier party',
	target_location_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the location.',
	loading_country_location_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the country the goods are loaded.',
	import_country_location_sid number(38,0) not null comment 'the unique identifier (surrogate key) for the country where the goods are imported.',
	actual_goods_movement_dt date comment 'the actual date of the movement of the goods.',
	planned_goods_movement_dt date comment 'the planned date of the movement of the goods.',
	picking_dt date comment 'the date when the goods are picked.',
	loading_dt date comment 'the date when the goods was loaded before they are transported.',
	transport_dt date comment 'the date when the transport of the goods has started.',
	actual_delivery_dt date comment 'the date when the goods are delivered.',
	planned_delivery_dt date comment 'the date when the goods are planned to delivered.',
	receipt_dt date comment 'the date when the goods are received by the receipient.',
	invoice_dt date comment 'the date on the invoice.',
	invoice_curr_cd varchar(50) not null comment 'the currency of the the invoice.',
	lidl_delivery_week_dt date comment 'a day in the week the delivery is supposed to happen ( usually a monday, wednesday or thursday )',
	lidl_delivery_week_fixed_fg boolean comment 'flag indicating if the delivery week is fixed',
	earliest_advertising_dt date comment 'earliest advertising date.',
	total_weight_meas number(38,5) comment 'fact - additive - the total weight of the goods including packaging, etc.',
	total_weight_unit_id number(38,0) not null comment 'the unit of measure the total weight is measured in.',
	net_weight_meas number(38,5) comment 'fact - additive - the net weight of the goods',
	net_weight_unit_id number(38,0) not null comment 'the unit of measure the net weight is measured in.',
	volume_meas number(38,5) comment 'fact - additive - the volume in space the goods take up.',
	volume_unit_id number(38,0) not null comment 'the unit of measure the volume is measured in.',
	package_cnt number(38,0) comment 'fact - additive - the count of packages.',
	sending_location_timezone_txt varchar(1000) comment 'descriptive attribute - supposed to contain the timezone information of the location that sends goods somewhere - source - lexis',
	recieving_location_timezone_txt varchar(1000) comment 'descriptive attribute - supposed to contain the timezone information of the location that recieves goods from somewhere - source - lexis',
	packing_instruction_nr varchar(250) comment 'the business identifier of the package instructions.',
	packing_space_max_cnt number(38,0) comment 'fact - additive - count of maximal parking spaces.',
	packing_space_total_cnt number(38,0) comment 'fact - additive - count of total parking spaces.',
	packing_space_leftover_cnt number(38,0) comment 'fact - additive - count of leftover parking spaces.',
	gross_weight_max_meas number(38,5) comment 'fact - additive - maximum gross weight.',
	gross_weight_total_meas number(38,5) comment 'fact - additive - the difference between maximum gross weight and leftover gross weight.',
	gross_weight_leftover_meas number(38,5) comment 'fact - additive - leftover gross weight.',
	load_length_max_meas number(38,5) comment 'fact - additive - total load length in meter.',
	load_length_total_meas number(38,5) comment 'fact - additive - total load length in meter.',
	load_length_leftover_meas number(38,5) comment 'fact - additive - leftover load length in meter.',
	monitoring_release_fg boolean comment 'released for monitoring the advertisement.',
	delivery_note_nr varchar(50) comment 'descriptive attribute - external delivery note number.',
	chargeback_min_dt date comment 'descriptive attribute - minimum date of charge back.',
	internal_delivery_uuid_nr varchar(100) comment 'descriptive attribute - internal uuid representing the delivery.',
	document_category_cd varchar(50) comment 'descriptive attribute - document category (e.g. delivery, return, stock transfer, etc.). determines the type of logistics document.',
	transport_identification_nr varchar(250) comment 'descriptive attribute - the transport identification number.',
	idoc_nr varchar(250) comment 'descriptive attribute - number of the idoc.',
	detention_time_day_cnt number(38,0) comment 'descriptive attribute - detention time for the container until a fee is charged.',
	dwh_created_tmsp timestamp_ltz(9) not null comment 'the point in time when this record was inserted into the table.',
	dwh_updated_tmsp timestamp_ltz(9) not null comment 'the point in time when this record was last modified. (in case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	dwh_src_file_name varchar(500) comment 'contains the name(s) of the input file(s) that delivered the record. it can be either the full path of the blog storage or the shortened file path',
	dwh_src_1_tmsp timestamp_ltz(9) not null comment 'the extraction timestamp of the record from the source',
	constraint pk_external_delivery primary key (delivery_nr, event_dt)
)comment='entity - transactional - transaction - shows the main common attributes of a delivery of goods from a supplier to a recipient/client via a carrier to an address. - source - lexis'
;